CREATE TABLE IF NOT EXISTS produtos (
    sku VARCHAR(50) PRIMARY KEY,
    nome VARCHAR(255) NOT NULL,
    preco NUMERIC(10, 2) NOT NULL,
    peso_kg NUMERIC(10, 2) NOT NULL,
    estoque INTEGER NOT NULL,
    fora_de_linha BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS clientes (
    cpf VARCHAR(11) PRIMARY KEY,
    email VARCHAR(255) NOT NULL,
    saldo_credito NUMERIC(10, 2) NOT NULL,
    criado_em TIMESTAMP NOT NULL
);

CREATE TABLE IF NOT EXISTS pedidos (
    id SERIAL PRIMARY KEY,
    cpf_cliente VARCHAR(11) NOT NULL REFERENCES clientes(cpf),
    situacao VARCHAR(50) NOT NULL,
    criado_em TIMESTAMP NOT NULL,
    pago_em TIMESTAMP,
    id_transacao VARCHAR(255),
    codigo_rastreio VARCHAR(255),
    resumo_json JSONB NOT NULL
);

CREATE TABLE IF NOT EXISTS itens_pedido (
    id SERIAL PRIMARY KEY,
    pedido_id BIGINT NOT NULL REFERENCES pedidos(id),
    sku VARCHAR(50) NOT NULL REFERENCES produtos(sku),
    quantidade INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS avisos (
    id SERIAL PRIMARY KEY,
    cpf_cliente VARCHAR(11) NOT NULL REFERENCES clientes(cpf),
    tipo VARCHAR(50) NOT NULL,
    pedido_id BIGINT NOT NULL REFERENCES pedidos(id),
    situacao VARCHAR(50) NOT NULL,
    criado_em TIMESTAMP NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_pedidos_cpf ON pedidos(cpf_cliente);
CREATE INDEX IF NOT EXISTS idx_itens_pedido ON itens_pedido(pedido_id);
CREATE INDEX IF NOT EXISTS idx_avisos_cpf ON avisos(cpf_cliente);

