package com.loja.pedidos.integration;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.loja.pedidos.LojaPedidosApplication;
import com.loja.pedidos.dto.DadosCompra;
import com.loja.pedidos.entity.Produto;
import com.loja.pedidos.repository.ProdutoRepository;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.web.servlet.MockMvc;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import java.math.BigDecimal;
import java.util.Arrays;

import static org.hamcrest.Matchers.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(classes = LojaPedidosApplication.class)
@AutoConfigureMockMvc
@Testcontainers
class PedidoIntegrationTest {
    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:15")
        .withDatabaseName("loja_test")
        .withUsername("test")
        .withPassword("test");

    @DynamicPropertySource
    static void configureProperties(DynamicPropertyRegistry registry) {
        registry.add("spring.datasource.url", postgres::getJdbcUrl);
        registry.add("spring.datasource.username", postgres::getUsername);
        registry.add("spring.datasource.password", postgres::getPassword);
    }

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ProdutoRepository produtoRepository;

    @Autowired
    private ObjectMapper objectMapper;

    @BeforeEach
    void setUp() {
        var produto = Produto.builder()
            .sku("CAM-001")
            .nome("Camiseta básica")
            .preco(new BigDecimal("79.90"))
            .pesoKg(new BigDecimal("0.30"))
            .estoque(50)
            .foraDeLinha(false)
            .build();

        produtoRepository.save(produto);
    }

    @Test
    void testCalcularResumoComSucesso() throws Exception {
        var dados = DadosCompra.builder()
            .cliente(new DadosCompra.Cliente("12345678901", "teste@exemplo.com"))
            .itens(Arrays.asList(new DadosCompra.Item("CAM-001", 2)))
            .cep("01310100")
            .regiao(DadosCompra.Regiao.SUDESTE)
            .modalidadeEntrega(DadosCompra.ModalidadeEntrega.RETIRADA_LOJA)
            .formaPagamento(DadosCompra.FormaPagamento.PIX)
            .parcelas(1)
            .nivelClube(DadosCompra.NivelClube.BRONZE)
            .build();

        mockMvc.perform(post("/checkout/resumo")
            .contentType(MediaType.APPLICATION_JSON)
            .content(objectMapper.writeValueAsString(dados)))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.subtotalProdutos", closeTo(159.80, 0.01)))
            .andExpect(jsonPath("$.frete", equalTo(0.0)))
            .andExpect(jsonPath("$.totalFinal", closeTo(159.80, 0.01)));
    }

    @Test
    void testRegistrarPedidoComSucesso() throws Exception {
        var dados = DadosCompra.builder()
            .cliente(new DadosCompra.Cliente("12345678901", "teste@exemplo.com"))
            .itens(Arrays.asList(new DadosCompra.Item("CAM-001", 1)))
            .cep("01310100")
            .regiao(DadosCompra.Regiao.SUDESTE)
            .modalidadeEntrega(DadosCompra.ModalidadeEntrega.RETIRADA_LOJA)
            .formaPagamento(DadosCompra.FormaPagamento.PIX)
            .parcelas(1)
            .nivelClube(DadosCompra.NivelClube.BRONZE)
            .build();

        mockMvc.perform(post("/pedidos")
            .contentType(MediaType.APPLICATION_JSON)
            .content(objectMapper.writeValueAsString(dados)))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.id", notNullValue()))
            .andExpect(jsonPath("$.situacao", equalTo("AGUARDANDO_PAGAMENTO")));
    }

    @Test
    void testCarrinhoVazioRetornaErro() throws Exception {
        var dados = DadosCompra.builder()
            .cliente(new DadosCompra.Cliente("12345678901", "teste@exemplo.com"))
            .itens(Arrays.asList())
            .cep("01310100")
            .regiao(DadosCompra.Regiao.SUDESTE)
            .modalidadeEntrega(DadosCompra.ModalidadeEntrega.RETIRADA_LOJA)
            .formaPagamento(DadosCompra.FormaPagamento.PIX)
            .parcelas(1)
            .nivelClube(DadosCompra.NivelClube.BRONZE)
            .build();

        mockMvc.perform(post("/checkout/resumo")
            .contentType(MediaType.APPLICATION_JSON)
            .content(objectMapper.writeValueAsString(dados)))
            .andExpect(status().isUnprocessableEntity())
            .andExpect(jsonPath("$.erro", equalTo("PEDIDO_INVALIDO")));
    }

    @Test
    void testProdutoInexistenteRetornaErro() throws Exception {
